const req = $input.first()?.json || {};
const body = req.body || req;
const tenantId = String(body.tenantId || 'common') .trim();
const clientId = String(body.clientId || '').trim();
const redirectUri = String(body.redirectUri || '').trim();
const requested = Array.isArray(body.connectors) ? body.connectors : ['sharepoint', 'dynamics'];
const requestId = 'cons-' + ($execution.id || 'na') + '-' + Date.now();
if (!clientId) {
  return [{ json: {
    ok: false, status: 'refused', reasonCode: 'empty', guidance: 'none',
    userMessage: 'A clientId is required to generate the admin consent URL.',
    adminConsentUrl: null, requiredScopes: [], entitlementChecklist: [], notes: [],
    diagnostics: { requestId: requestId, workflow: 'prism-09-admin-consent-helper' }
  } }];
}
const SCOPE_MAP = {
  sharepoint: { scope: 'https://graph.microsoft.com/Sites.Read.All', note: 'Tenant-wide SharePoint read. Grants access to all site libraries the requesting users can already reach.' },
  dynamics: { scope: 'SCOPE_DYNAMICS_ORG_USER_IMPERSONATION', note: 'Dynamics 365 Dataverse user_impersonation for <org>.crm*.dynamics.com - replace SCOPE with the real org resource in the consent URL.' },
  mail: { scope: 'https://graph.microsoft.com/Mail.Read', note: 'Usually NOT required - personal Mail.Read needs no admin consent. Included only if your tenant policy blocks user consent.' },
  files: { scope: 'https://graph.microsoft.com/Files.Read', note: 'User-level file read. Admin consent only needed when tenant policy blocks user consent.' }
};
const wanted = requested.filter(function (c) { return SCOPE_MAP[c]; });
const scopeParams = [];
const requiredScopes = [];
const entitlementChecklist = [];
const notes = [];
wanted.forEach(function (c) {
  const info = SCOPE_MAP[c];
  requiredScopes.push(info.scope);
  notes.push(c + ': ' + info.note);
});
if (wanted.indexOf('sharepoint') >= 0) {
  scopeParams.push('Sites.Read.All');
  entitlementChecklist.push('Admin: grant tenant-wide consent once for Sites.Read.All.');
  entitlementChecklist.push('User: must already have access to the target SharePoint sites in Entra ID.');
}
if (wanted.indexOf('dynamics') >= 0) {
  entitlementChecklist.push('User: must hold a Dynamics 365 license (SKU check via /me/licenseDetails).');
  entitlementChecklist.push('User: must have a Dataverse security role (WhoAmI probe).');
  entitlementChecklist.push('Admin: set a Dataverse environment + security role in Power Platform Admin Center.');
  entitlementChecklist.push('Scope: https://<org>.crm<region>.dynamics.com/user_impersonation must be appended to the consent URL.');
}
if (wanted.indexOf('mail') >= 0 || wanted.indexOf('files') >= 0) {
  entitlementChecklist.push('Personal-tier connectors (Mail.Read / Files.Read) normally need NO admin consent.');
}
const encodedScopes = encodeURIComponent(requiredScopes.join(' '));
const encodedRedirect = encodeURIComponent(redirectUri || 'https://app.prism.example/auth/callback');
const adminConsentUrl = 'https://login.microsoftonline.com/' + encodeURIComponent(tenantId) + '/adminconsent?client_id=' + encodeURIComponent(clientId) + '&redirect_uri=' + encodedRedirect + (scopeParams.length ? '&scope=' + encodedScopes : '');
return [{ json: {
  ok: true,
  status: 'success',
  adminConsentUrl: adminConsentUrl,
  requiredScopes: requiredScopes,
  entitlementChecklist: entitlementChecklist,
  notes: notes,
  clientId: clientId,
  tenantId: tenantId,
  diagnostics: { requestId: requestId, workflow: 'prism-09-admin-consent-helper' }
} }];
